package team.platforma.apppermissions

actual object PermissionX {
    actual fun gallery(result: (Permission, Boolean) -> Unit) {
        result(Permission.Gallery, true)
    }

    actual fun geolocationOnAppUsing(result: (Permission, Boolean) -> Unit) {
        result(Permission.GeolocationOnAppUsing, true)
    }

    actual fun notification(result: (Permission, Boolean) -> Unit) {
        result(Permission.Notification, true)
    }
    actual fun requestMultiply(
        permissionList: List<Permission>,
        result: (Map<Permission, Boolean>) -> Unit
    ) {
        val permissions = mutableListOf<(granted: (Permission, Boolean) -> Unit) -> Unit>()
        permissionList.forEach {
            when (it) {
                Permission.Gallery -> {
                    permissions.add(::gallery)
                }

                Permission.GeolocationOnAppUsing -> {
                    permissions.add(::geolocationOnAppUsing)
                }

                Permission.Notification -> {
                    permissions.add(::notification)
                }
                else -> {}
            }
        }

        val resultMap: MutableMap<Permission, Boolean> = mutableMapOf()

        fun requestNextPermission(index: Int) {
            if (index < permissions.size) {
                permissions[index] { permission, granted ->
                    resultMap[permission] = granted
                    requestNextPermission(index + 1)
                }
            } else {
                result(resultMap)
            }
        }
        requestNextPermission(0)
    }

    actual fun openAppSettings() {}

    actual fun openPhoneSettings(settings: Settings) {}

    /**
     * Info.plist:
     *
     * &lt;key&gt;LSApplicationQueriesSchemes&lt;/key&gt;
     *
     * &lt;array&gt;
     *
     *     <string>openvpn</string>
     *
     * &lt;/array&gt;
     */
    actual fun startOpenVpn(){
    }
    actual fun openVpnIsInstalled():Boolean{
        return false
    }

}